"use client";

import { motion, useReducedMotion } from "framer-motion";

export function PrimaryButton({ children }: { children: React.ReactNode }) {
  const shouldReduceMotion = useReducedMotion();

  return (
    <motion.button
      whileHover={shouldReduceMotion ? undefined : { y: -2 }}
      whileTap={{ scale: 0.96, y: 0 }}
      transition={{ type: "spring", stiffness: 500, damping: 30 }}
      className="group relative inline-flex items-center justify-center overflow-hidden rounded-lg bg-emerald-700 px-5 py-2.5 text-sm font-medium text-white shadow-[0_1px_2px_rgba(4,120,87,0.3)] transition-[box-shadow,background-color] duration-300 hover:bg-emerald-600 hover:shadow-[0_12px_24px_-8px_rgba(4,120,87,0.65)] focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-700 active:bg-emerald-800 dark:bg-emerald-500 dark:shadow-[0_1px_2px_rgba(16,185,129,0.35)] dark:hover:bg-emerald-400 dark:hover:shadow-[0_12px_24px_-8px_rgba(16,185,129,0.55)] dark:focus-visible:outline-emerald-400 dark:active:bg-emerald-600"
    >
      <span
        aria-hidden
        className="pointer-events-none absolute inset-0 -translate-x-full bg-gradient-to-r from-transparent via-white/30 to-transparent transition-transform duration-700 ease-out group-hover:translate-x-full motion-reduce:hidden"
      />
      <span className="relative">{children}</span>
    </motion.button>
  );
}
